 const form=$('#player-form');if(form){form.querySelector('[name=name]').placeholder='Ej. Matías Rojas';form.querySelector('[name=number]').placeholder='1–99';for(const option of form.querySelector('[name=position]').options){option.value=option.value;option.textContent={POR:'Portero',DEF:'Defensa',MED:'Mediocampista',DEL:'Delantero'}[option.value]||option.value;}}
