function defaultRulesView(){return heading('Reglamento','Propuesta de bases · pendiente de validación de la organización')+`<div class="panel rule"><h3>01 / Formato de competencia</h3><p>La liga usa una tabla de puntos. Las copas son competencias independientes de eliminación directa, con 4, 8 o 16 equipos y desempate por penales. Estas bases deben ser confirmadas por la organización.</p><h3>02 / Puntaje y desempates</h3><p>Victoria: 3 puntos. Empate: 1 punto. Derrota: 0 puntos. El orden se define por puntos, diferencia de gol y goles a favor. Si persiste la igualdad, la organización resolverá el desempate; mientras tanto se muestran por nombre.</p><h3>03 / Planteles y alineaciones</h3><p>Cada capitán gestiona únicamente su equipo. Las alineaciones se componen de 7 titulares y se bloquean cuando el partido está en juego o finalizado.</p><h3>04 / Resultados oficiales</h3><p>Solo la administración registra marcadores, estado del partido y eventos. La tabla incluye únicamente partidos finalizados.</p></div>`;}
// Fixed tactical slots: goalkeeper first, then each line from defence to attack.
const FORMATIONS = {
 '3-1-2': {size:7, note:'Tres defensas, un mediocentro y dos delanteros.',lines:[3,1,2]},
 '3-2-1': {size:7, note:'Tres defensas, dos medios y un delantero.',lines:[3,2,1]},
 '3-1-1-1': {size:7, note:'Tres defensas, un pivote, un mediapunta y un punta.',lines:[3,1,1,1]},
 '2-3-1': {size:7, note:'Dos defensas, tres medios y un delantero.',lines:[2,3,1]},
 '2-2-2': {size:7, note:'Dos defensas, dos medios y dos delanteros.',lines:[2,2,2]},
 '2-1-2-1': {size:7, note:'Dos defensas, un pivote, dos medios y un punta.',lines:[2,1,2,1]},
};
function formationSlots(name){
 const f=FORMATIONS[name];if(!f)return [];
 const result=[{x:50,y:89,label:'Portero'}];
 f.lines.forEach((count,line)=>{const y=70-line*(54/Math.max(1,f.lines.length-1));
  for(let i=0;i<count;i++)result.push({x:count===1?50:14+i*72/(count-1),y,label:`${line===0?'Defensa':line===f.lines.length-1?'Ataque':'Medio '+line} · ${count===1?'centro':i+1}`});
 });return result;
}
function lineupIds(l){
 if(!l)return [];
 if(l.slot_player_ids?.length)return l.slot_player_ids;
 // Legacy lineups have no positional order. Use a stable order, clearly identified in UI.
 return [...l.player_ids].sort((a,b)=>['POR','DEF','MED','DEL'].indexOf(player(a)?.position)-['POR','DEF','MED','DEL'].indexOf(player(b)?.position)||(player(a)?.number||0)-(player(b)?.number||0));
}
function tacticalPitch(formation,ids=[]){return `<div class="tactical-pitch" aria-label="Cancha: ${esc(formation)}"><div class="pitch-circle"></div><div class="pitch-box top"></div><div class="pitch-box bottom"></div>${formationSlots(formation).map((slot,i)=>{const p=player(ids[i]);return `<div class="pitch-player ${p?'':'vacant'}" style="left:${slot.x}%;top:${slot.y}%"><span class="shirt">${p?p.number:'–'}</span><span>${esc(p?.name||slot.label)}</span></div>`;}).join('')}</div>`;}
function isSevenLineup(l){return !!l&&FORMATIONS[l.formation]?.size===7&&l.player_ids?.length===7;}
lineupView=function(m,side){const l=data.lineups.find(l=>l.match_id===m.id&&l.team_id===side),valid=isSevenLineup(l);return `<div class="filters lineup-switch">${[m.home_id,m.away_id].filter(Boolean).map(id=>`<button aria-pressed="${side===id}" class="${side===id?'selected':''}" data-lineup-side="${id}" data-match-id="${m.id}">${crest(team(id),true)}${esc(team(id).name)}</button>`).join('')}</div>${!l?'<div class="empty">Alineación pendiente de publicación.</div>':!valid?`<div class="notice">Esta alineación anterior no corresponde a fútbol 7. La organización debe revisarla; se conserva el registro original.</div><div class="lineup-list">${l.player_ids.map(player).filter(Boolean).map(p=>`<div class="lineup-person"><b>${p.number}</b><span>${esc(p.name)}</span></div>`).join('')}</div>`:`<div class="lineup-caption"><strong>${esc(team(side).name)}</strong><span class="tag">${esc(l.formation)} · Fútbol 7</span></div><p class="form-help">${esc(FORMATIONS[l.formation].note)}${!l.slot_player_ids?.length?' Posiciones antiguas ordenadas por rol y dorsal; el capitán puede asignarlas antes del inicio.':''}</p>${tacticalPitch(l.formation,lineupIds(l))}`}`;};
function lineupEditor(id){const m=data.matches.find(m=>m.id===id),target=$('#lineup-editor');if(!m){target.innerHTML='';return;}if(m.status!=='scheduled'){target.innerHTML='<p class="notice">La alineación está bloqueada porque el partido ya comenzó.</p>'+lineupView(m,selectedTeam);return;}
 const l=data.lineups.find(l=>l.match_id===id&&l.team_id===selectedTeam),valid=isSevenLineup(l),formation=valid?l.formation:'3-1-2';
 target.innerHTML=`<form id="lineup-form" data-id="${id}" class="form-grid"><label>Formación<select name="formation">${[7].map(size=>`<optgroup label="Fútbol ${size}">${Object.entries(FORMATIONS).filter(([,f])=>f.size===size).map(([key])=>`<option value="${key}" ${key===formation?'selected':''}>${key}</option>`).join('')}</optgroup>`).join('')}</select></label><p id="formation-description" class="form-help"></p><div class="formation-workspace"><div id="formation-preview"></div><div id="formation-slots"></div></div><button>Publicar alineación</button></form>`;
 renderFormationEditor(formation,valid?lineupIds(l):[]);if(l&&!valid)target.insertAdjacentHTML('afterbegin','<p class="notice">Revisa esta alineación anterior: elige un esquema de fútbol 7 y asigna sus siete titulares.</p>');updateSelectionProgress();
};
function renderFormationEditor(formation,ids=[]){const roster=data.players.filter(p=>p.team_id===selectedTeam);$('#formation-description').textContent=FORMATIONS[formation].note+' Asigna un jugador distinto a cada posición. Se mantendrá exactamente esta distribución.';$('#formation-slots').innerHTML=formationSlots(formation).map((slot,i)=>`<label>${i+1}. ${esc(slot.label)}<select data-lineup-slot="${i}" required><option value="">Seleccionar jugador</option>${roster.map(p=>`<option value="${p.id}" ${ids[i]===p.id?'selected':''}>${p.number} · ${esc(p.name)} (${p.position})</option>`).join('')}</select></label>`).join('');syncFormationPreview();}
function syncFormationPreview(){const form=$('#lineup-form');if(!form)return;const slots=[...form.querySelectorAll('[data-lineup-slot]')],ids=slots.map(s=>s.value);for(const select of slots)for(const o of select.options)o.disabled=!!o.value&&o.value!==select.value&&ids.includes(o.value);$('#formation-preview').innerHTML=tacticalPitch(form.elements.formation.value,ids);updateSelectionProgress();}

function eventTimeline(m,editable=false){const events=data.events.filter(e=>e.match_id===m.id).sort((a,b)=>b.minute-a.minute||a.id.localeCompare(b.id));return `<div class="timeline-team-head"><span>${crest(team(m.home_id),true)}${esc(team(m.home_id).name)}</span><span>MIN</span><span>${crest(team(m.away_id),true)}${esc(team(m.away_id).name)}</span></div><ol class="match-timeline split-timeline">${events.map(e=>`<li class="${e.team_id===m.home_id?'home-event':'away-event'}"><time>${e.minute}′</time><div class="timeline-event"><span class="event-kind">${eventLabel(e.type)}</span><strong>${esc(player(e.player_id)?.name||'Jugador')}</strong>${editable?`<button type="button" class="text-button" data-delete-event="${e.id}" aria-label="Eliminar ${esc(player(e.player_id)?.name)} minuto ${e.minute}">Eliminar</button>`:''}</div></li>`).join('')||'<li class="timeline-empty">Sin eventos registrados.</li>'}</ol>`;}
const compactScoreEditor=scoreEditor;
