const matchBrowsers={};
function installMatchBrowser(id){const select=$('#'+id);if(!select)return;const key=id==='manage-match'?'matches':'lineups';const state=matchBrowsers[id]??={q:'',status:'all',competition:'all',page:0};select.parentElement.hidden=true;
 select.parentElement.insertAdjacentHTML('afterend',`<section class="match-browser" data-browser="${id}"><div class="browser-filters"><label>Buscar encuentro<input type="search" data-browser-query placeholder="Equipo, copa, fecha o cancha" value="${esc(state.q)}"></label><label>Estado<select data-browser-status>${[['all','Todos'],['scheduled','Programados'],['live','En vivo'],['finished','Finalizados']].map(([v,l])=>`<option value="${v}" ${v===state.status?'selected':''}>${l}</option>`).join('')}</select></label><label>Competencia<select data-browser-competition><option value="all">Todas</option>${options(data.competitions||[],'id','name',state.competition)}</select></label></div><div class="browser-results" aria-live="polite"></div></section>`);renderMatchBrowser(id);
}
const normalizeSearch=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();
function browserMatches(id){const state=matchBrowsers[id];return data.matches.filter(m=>(id==='manage-match'||[m.home_id,m.away_id].includes(selectedTeam))&&(state.status==='all'||m.status===state.status)&&(state.competition==='all'||m.competition_id===state.competition)&&normalizeSearch(`${team(m.home_id).name} ${team(m.away_id).name} ${matchStage(m)} ${m.venue} ${m.kickoff.slice(0,10)} ${date(m.kickoff)}`).includes(normalizeSearch(state.q))).sort((a,b)=>({live:0,scheduled:1,finished:2}[a.status]-{live:0,scheduled:1,finished:2}[b.status])||(a.status==='finished'?b.kickoff.localeCompare(a.kickoff):a.kickoff.localeCompare(b.kickoff))||a.id.localeCompare(b.id));}
function renderMatchBrowser(id){const target=$(`[data-browser="${id}"] .browser-results`);if(!target)return;const state=matchBrowsers[id],rows=browserMatches(id),pages=Math.max(1,Math.ceil(rows.length/6));state.page=Math.min(state.page,pages-1);const selected=id==='manage-match'?selectedMatch:managementLineup;
 target.innerHTML=`<div class="match-choice-grid">${rows.slice(state.page*6,state.page*6+6).map(m=>`<button type="button" class="match-choice ${m.id===selected?'selected':''}" data-pick-match="${m.id}" data-picker="${id}" aria-pressed="${m.id===selected}"><span class="match-choice-meta">${statusText[m.status]} · ${esc(matchStage(m))}</span><strong>${crest(team(m.home_id),true)}${esc(team(m.home_id).name)} <span>vs</span> ${esc(team(m.away_id).name)}${crest(team(m.away_id),true)}</strong><small>${date(m.kickoff)} · ${esc(m.venue)}</small>${id==='lineup-match'?`<small>${data.lineups.some(l=>l.match_id===m.id&&l.team_id===selectedTeam)?'Alineación publicada':'Pendiente'}${m.status!=='scheduled'?' · Solo lectura':''}</small>`:''}</button>`).join('')||'<p class="empty">No hay encuentros con estos filtros.</p>'}</div><div class="browser-pagination"><span>${rows.length} encuentros · Página ${state.page+1} de ${pages}</span><button type="button" class="outline" data-page-step="-1" ${state.page===0?'disabled':''} aria-label="Página anterior">←</button><button type="button" class="outline" data-page-step="1" ${state.page+1>=pages?'disabled':''} aria-label="Página siguiente">→</button></div>`;
}

