function bracketCard(m,c){const finalRound=Math.log2(c.size),third=m.round===finalRound&&m.slot===2;return `<button class="bracket-match ${m.status==='live'?'is-live':''}" data-open-match="${m.id}"><span class="bracket-meta"><span>${m.status==='scheduled'?date(m.kickoff):statusText[m.status]}</span><span>${third?'TERCER LUGAR':'CRUCE '+m.slot}</span></span>${['home','away'].map((side,i)=>`<span class="bracket-team ${winner(m)===m[side+'_id']&&m[side+'_id']?'winner':''}"><span>${crest(team(m[side+'_id']),true)}${esc(m[side+'_id']?team(m[side+'_id']).name:third?'Perdedor semifinal '+(i+1):m.round>1?'Ganador cruce '+((m.slot-1)*2+i+1):'Por definir')}</span><b>${m.status==='scheduled'?'–':m[side+'_score']}</b></span>`).join('')}${m.penalty_home!=null?`<small>Penales ${m.penalty_home} – ${m.penalty_away}</small>`:''}</button>`;}
cupsView=function(){const cups=(data.competitions||[]).filter(c=>c.format==='cup');if(!cups.some(c=>c.id===selectedCup))selectedCup=cups[0]?.id||'';const c=competition(selectedCup);if(!c)return heading('El camino a la copa','Cada cruce cuenta.')+'<div class="panel empty">Todavía no hay copas creadas.</div>';
 const rounds=Math.log2(c.size),games=data.matches.filter(m=>m.competition_id===c.id),final=games.find(m=>m.round===rounds&&m.slot===1),third=games.find(m=>m.round===rounds&&m.slot===2),champion=winner(final),step=136,col=268,card=224,height=c.size/2*step;
 const paths=[];for(let r=1;r<rounds;r++)for(let slot=1;slot<=c.size/2**r;slot++){const y=(slot-.5)*step*2**(r-1),nextY=(Math.ceil(slot/2)-.5)*step*2**r,x=(r-1)*col+card;paths.push(`<path d="M ${x} ${y} H ${x+22} V ${nextY} H ${r*col}"/>`);}
 return heading('El camino a la copa','Cruces conectados, desde la primera ronda hasta la final.')+`<div class="cup-banner"><div class="cup-symbol">${icon('trophy')}</div><div><span class="eyebrow">ELIMINACIÓN DIRECTA · ${c.size} EQUIPOS</span><h2>${esc(c.name)}</h2></div>${champion?`<div class="champion"><small>CAMPEÓN</small><strong>${crest(team(champion),true)}${esc(team(champion).name)}</strong></div>`:''}</div><div class="toolbar"><label>Competencia<select id="cup-select">${options(cups,'id','name',c.id)}</select></label><span class="muted">Desliza para recorrer el cuadro →</span></div><div class="bracket-scroll" tabindex="0" aria-label="Cuadro de ${esc(c.name)}"><div class="connected-bracket" style="width:${rounds*col-44}px"><div class="bracket-headings">${Array.from({length:rounds},(_,i)=>`<h3 style="left:${i*col}px">${phaseName(c.size,i+1)}</h3>`).join('')}</div><div class="bracket-canvas" style="height:${height}px"><svg class="bracket-lines" width="${rounds*col-44}" height="${height}" aria-hidden="true">${paths.join('')}</svg>${games.filter(m=>!(m.round===rounds&&m.slot===2)).map(m=>`<div class="bracket-node" style="left:${(m.round-1)*col}px;top:${(m.slot-.5)*step*2**(m.round-1)}px">${bracketCard(m,c)}</div>`).join('')}</div></div></div>${third?`<section class="third-place"><h3>Tercer y cuarto lugar</h3><p class="form-help">Los perdedores de las dos semifinales.</p>${bracketCard(third,c)}</section>`:''}<section class="panel rule cup-rules"><h3>Reglamento · ${esc(c.name)}</h3><div class="rules-text">${esc(c.rules||'La organización aún no ha publicado el reglamento de esta copa.')}</div>${isAdmin()?cupEditForm(c):''}</section>`;
};

const fallbackCrest=crest;
crest=function(t,mini=false){const url=t.crest_path&&window.BENJAIX_CONFIG?.supabaseUrl?`${window.BENJAIX_CONFIG.supabaseUrl}/storage/v1/object/public/team-crests/${t.crest_path}`:t.demo_crest;return `<span class="crest-wrap ${mini?'mini':''}">${fallbackCrest(t,mini)}${url?`<img class="crest-image" src="${esc(url)}" alt="Escudo de ${esc(t.name)}" width="80" height="80" loading="lazy" decoding="async">`:''}</span>`;};
document.addEventListener('error',e=>{if(e.target.matches?.('.crest-image'))e.target.remove();},true);
async function encodeCrest(file){if(!file||!file.size)throw Error('Selecciona una imagen.');if(file.size>12*1024*1024)throw Error('La imagen original no puede superar 12 MB.');let bitmap;try{bitmap=await createImageBitmap(file);}catch{throw Error('No se pudo abrir esta imagen. Prueba con PNG, JPG, WebP o AVIF.');}try{const canvas=document.createElement('canvas'),scale=Math.min(1,256/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);for(const quality of [.85,.7,.5]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',quality));if(!blob||blob.type!=='image/webp')throw Error('Este navegador no puede convertir a WebP. Actualízalo para subir el escudo.');if(blob.size<=65536)return blob;}throw Error('No se pudo reducir el escudo a 64 KB. Prueba una imagen más simple.');}finally{bitmap.close();}}
function crestEditor(){return `<form id="crest-form" data-team-id="${selectedTeam}" class="form-grid crest-editor"><h3>Escudo del equipo</h3><div id="crest-preview">${crest(team(selectedTeam))}</div><label>Imagen del escudo<input type="file" name="crest_file" accept="image/*" required></label><p class="form-help">Conservamos la proporción y la transparencia. Convertimos a WebP, máximo 256 px y 64 KB antes de subir.</p><button>Guardar escudo</button><p id="crest-feedback" role="status"></p></form>`;}
let crestPreviewUrl=null,crestPreviewVersion=0;

const upgradePanel=enhancePanel;
enhancePanel=function(){upgradePanel();if(location.hash!=='#panel'||!(demo?demoProfile:profile))return;installMatchBrowser('manage-match');installMatchBrowser('lineup-match');const edit=$('#edit-team');if(edit)edit.insertAdjacentHTML('afterend',crestEditor());if(isAdmin()){const cups=$('.management-section[data-section="cups"]');if(cups)cups.insertAdjacentHTML('afterbegin',`<div class="existing-cups"><h3>Copas existentes</h3>${(data.competitions||[]).filter(c=>c.format==='cup').map(cupEditForm).join('')||'<p class="muted">Aún no hay copas.</p>'}</div>`);const form=$('#cup-form');if(form){const label=document.createElement('label');label.innerHTML='Reglamento de esta copa<textarea name="rules" rows="6" maxlength="20000" placeholder="Bases, duración, sanciones y desempates…"></textarea>';form.querySelector('button').before(label);}}};

async function handleUpgradeForm(f,v,fd){
 if(f.id==='lineup-form'){const ids=[...f.querySelectorAll('[data-lineup-slot]')].map(s=>s.value),formation=v.formation;if(!FORMATIONS[formation]||ids.length!==FORMATIONS[formation].size||ids.some(id=>!id)||new Set(ids).size!==ids.length)throw Error('Completa cada posición con un jugador distinto.');const m=data.matches.find(m=>m.id===f.dataset.id);if(m.status!=='scheduled')throw Error('El partido ya comenzó.');if(ids.some(id=>player(id)?.team_id!==selectedTeam))throw Error('Todos los jugadores deben pertenecer al equipo.');const old=data.lineups.find(l=>l.match_id===m.id&&l.team_id===selectedTeam);await save('lineups',{match_id:m.id,team_id:selectedTeam,formation,player_ids:ids,slot_player_ids:ids},old?.id);render();return true;}
 if(f.id==='rules-form'||f.dataset.cupEdit){if(!isAdmin())throw Error('Solo la administración puede editar las bases.');const id=f.dataset.cupEdit||f.dataset.id,row={rules:v.rules.trim()};if(f.dataset.cupEdit)row.name=v.name.trim();await save('competitions',row,id);render();return true;}
 if(f.id==='cup-form'){const ids=fd.getAll('team_ids');if(![4,8,16].includes(ids.length))throw Error('Selecciona 4, 8 o 16 equipos.');if(!isAdmin())throw Error('Solo la administración puede crear copas.');if(demo){selectedCup=addDemoCup(v.cup_name.trim(),ids,v.first_kickoff,v.cup_venue);competition(selectedCup).rules=v.rules.trim();localStorage.setItem('benjaix-demo-v2',JSON.stringify(data));}else selectedCup=await rpc('create_cup_with_rules',{cup_name:v.cup_name.trim(),team_ids:ids,first_kickoff:new Date(v.first_kickoff).toISOString(),cup_venue:v.cup_venue,cup_rules:v.rules.trim()});location.hash='copa';render();toast('Copa creada');return true;}
 if(f.id==='crest-form'){const id=f.dataset.teamId,blob=await encodeCrest(fd.get('crest_file'));if(demo){const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});await save('teams',{demo_crest:base64},id);}else{const old=team(id).crest_path,path=`${id}/${uid()}.webp`,bucket=db.storage.from('team-crests');const {error}=await bucket.upload(path,blob,{contentType:'image/webp',cacheControl:'31536000',upsert:false});if(error)throw Error('No se pudo subir el escudo: '+error.message);const update=await db.from('teams').update({crest_path:path}).eq('id',id).select('id');if(update.error||!update.data?.length){await bucket.remove([path]);throw Error(update.error?.message||'No tienes permiso para actualizar este escudo.');}if(old){const removed=await bucket.remove([old]);if(removed.error)console.warn('No se pudo retirar el escudo anterior.');}await refresh(['teams']);}render();toast(`Escudo guardado en WebP · ${Math.ceil(blob.size/1024)} KB`);return true;}
 return false;
}

document.addEventListener('click',e=>{const pick=e.target.closest('[data-pick-match]');if(pick){const select=$('#'+pick.dataset.picker);select.value=pick.dataset.pickMatch;select.dispatchEvent(new Event('change',{bubbles:true}));renderMatchBrowser(select.id);}const page=e.target.closest('[data-page-step]');if(page){const id=page.closest('[data-browser]').dataset.browser;matchBrowsers[id].page+=Number(page.dataset.pageStep);renderMatchBrowser(id);}});
document.addEventListener('input',e=>{if(e.target.matches('[data-browser-query]')){const id=e.target.closest('[data-browser]').dataset.browser;matchBrowsers[id].q=e.target.value;matchBrowsers[id].page=0;renderMatchBrowser(id);}});
document.addEventListener('change',async e=>{const el=e.target;if(el.matches('[data-browser-status],[data-browser-competition]')){const id=el.closest('[data-browser]').dataset.browser;matchBrowsers[id][el.hasAttribute('data-browser-status')?'status':'competition']=el.value;matchBrowsers[id].page=0;renderMatchBrowser(id);}if(el.id==='stats-sort'){statMetric=el.value;render();}if(el.matches('#lineup-form [name=formation]')){const ids=[...$('#lineup-form').querySelectorAll('[data-lineup-slot]')].map(s=>s.value);renderFormationEditor(el.value,ids);}if(el.matches('[data-lineup-slot]'))syncFormationPreview();if(el.matches('[name=crest_file]')){const version=++crestPreviewVersion;try{const blob=await encodeCrest(el.files[0]);if(version!==crestPreviewVersion)return;if(crestPreviewUrl)URL.revokeObjectURL(crestPreviewUrl);crestPreviewUrl=URL.createObjectURL(blob);$('#crest-preview').innerHTML=`<img src="${crestPreviewUrl}" width="80" height="80" alt="Vista previa del escudo">`;$('#crest-feedback').textContent=`WebP listo · ${Math.ceil(blob.size/1024)} KB`;}catch(error){if(version===crestPreviewVersion)$('#crest-feedback').textContent=error.message;}}});

// Paginate initial snapshots to avoid silently truncating at the API's row limit.
async function readTable(table){const rows=[],pageSize=500;const order=['expert_totals','expert_candidates'].includes(table)?['match_id','player_id']:table==='expert_polls'?['match_id']:['id'];for(let offset=0;;offset+=pageSize){let query=db.from(table).select('*');for(const column of order)query=query.order(column);const result=await query.range(offset,offset+pageSize-1);if(result.error)return result;rows.push(...result.data);if(result.data.length<pageSize)return {data:rows,error:null};}}
const realtimeTables=new Set();let realtimeTimer=null,realtimeRunning=false,realtimeDirty=false;
function applyRealtime(payload){const {table,eventType}=payload,rows=data[table];if(!Array.isArray(rows))return false;const keys=['expert_totals','expert_candidates'].includes(table)?['match_id','player_id']:table==='expert_polls'?['match_id']:['id'],record=eventType==='DELETE'?payload.old:payload.new;if(!record||keys.some(k=>record[k]==null))return false;const index=rows.findIndex(row=>keys.every(k=>row[k]===record[k]));if(eventType==='DELETE'){if(index>=0)rows.splice(index,1);}else if(['INSERT','UPDATE'].includes(eventType)){if(index>=0)rows[index]={...rows[index],...record};else rows.push(record);}else return false;return true;}
function queueRealtime(payload){const allowed=['teams','players','matches','events','lineups','competitions','expert_polls','expert_candidates','expert_totals'];if(!allowed.includes(payload.table))return;if(!applyRealtime(payload))realtimeTables.add(payload.table);realtimeDirty=true;clearTimeout(realtimeTimer);realtimeTimer=setTimeout(flushRealtime,600);}
async function flushRealtime(){if(realtimeRunning){realtimeTimer=setTimeout(flushRealtime,600);return;}const tables=[...realtimeTables];realtimeTables.clear();realtimeRunning=true;try{if(tables.length)await refresh(tables);else if(realtimeDirty){if(location.hash!=='#panel'||!document.activeElement?.closest('form'))render();if($('#modal').open&&activeMatch)showMatch(activeMatch.id,activeMatch.side);}}catch{toast('No se pudieron sincronizar los cambios. Recarga para actualizar.');}finally{realtimeDirty=false;realtimeRunning=false;if(realtimeTables.size)realtimeTimer=setTimeout(flushRealtime,600);}}

init();
